1	// Package entitlements implements the seat-quota entitlement domain:
2	// entitlement creation, idempotent reservations, and confirm/release
3	// settlement, persisted in PostgreSQL.
4	package entitlements
5	
6	import (
7		"context"
8		"errors"
9		"fmt"
10		"regexp"
11		"time"
12	
13		"github.com/jackc/pgx/v5"
14		"github.com/jackc/pgx/v5/pgconn"
15		"github.com/jackc/pgx/v5/pgxpool"
16	)
17	
18	// Error codes returned to API callers. They are stable identifiers; clients
19	// should branch on Code, not on Message.
20	const (
21		CodeInvalidRequest          = "invalid_request"
22		CodeEntitlementExists       = "entitlement_exists"
23		CodeEntitlementNotFound     = "entitlement_not_found"
24		CodeEntitlementNotActive    = "entitlement_not_active"
25		CodeInsufficientQuota       = "insufficient_quota"
26		CodeReservationNotFound     = "reservation_not_found"
27		CodeReservationParamChanged = "reservation_param_mismatch"
28		CodeReservationSettled      = "reservation_already_settled"
29	)
30	
31	// Error is a domain failure with a stable machine-readable code.
32	type Error struct {
33		Code    string
34		Message string
35	}
36	
37	func (e *Error) Error() string { return e.Code + ": " + e.Message }
38	
39	func fail(code, format string, args ...any) *Error {
40		return &Error{Code: code, Message: fmt.Sprintf(format, args...)}
41	}
42	
43	// Reservation lifecycle states.
44	const (
45		StatusPending   = "pending"
46		StatusConfirmed = "confirmed"
47		StatusReleased  = "released"
48	)
49	
50	// Settlement actions.
51	const (
52		ActionConfirm = "confirm"
53		ActionRelease = "release"
54	)
55	
56	// Entitlement is a team's seat-quota grant over a validity window.
57	type Entitlement struct {
58		EntitlementID string    `json:"entitlement_id"`
59		SeatsTotal    int64     `json:"seats_total"`
60		QuotaTotal    int64     `json:"quota_total"`
61		ValidFrom     time.Time `json:"valid_from"`
62		ValidTo       time.Time `json:"valid_to"`
63	}
64	
65	// Reservation is a quota hold placed by an internal sub-team.
66	type Reservation struct {
67		ReservationID string     `json:"reservation_id"`
68		Amount        int64      `json:"amount"`
69		Status        string     `json:"status"`
70		SettledAt     *time.Time `json:"settled_at,omitempty"`
71		CreatedAt     time.Time  `json:"created_at"`
72	}
73	
74	// View is the per-entitlement quota and reservation report.
75	type View struct {
76		EntitlementID   string        `json:"entitlement_id"`
77		SeatsTotal      int64         `json:"seats_total"`
78		QuotaTotal      int64         `json:"quota_total"`
79		UsedAmount      int64         `json:"used_amount"`
80		ReservedAmount  int64         `json:"reserved_amount"`
81		AvailableAmount int64         `json:"available_amount"`
82		Status          string        `json:"status"` // pending, active or expired
83		ValidFrom       time.Time     `json:"valid_from"`
84		ValidTo         time.Time     `json:"valid_to"`
85		Reservations    []Reservation `json:"reservations"`
86	}
87	
88	var identifierPattern = regexp.MustCompile(`^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$`)
89	
90	func validIdentifier(kind, value string) *Error {
91		if !identifierPattern.MatchString(value) {
92			return fail(CodeInvalidRequest, "%s must be 1-128 characters of letters, digits, dot, underscore or dash, and start with a letter or digit", kind)
93		}
94		return nil
95	}
96	
97	// Store persists entitlements and reservations in PostgreSQL. All mutating
98	// operations take a row lock on the entitlement so concurrent reservations
99	// and settlements on the same entitlement are serialized.
100	type Store struct {
101		pool *pgxpool.Pool
102	}
103	
104	func NewStore(pool *pgxpool.Pool) *Store { return &Store{pool: pool} }
105	
106	// Migrate creates the schema if it does not exist yet.
107	func (s *Store) Migrate(ctx context.Context) error {
108		_, err := s.pool.Exec(ctx, `
109	CREATE TABLE IF NOT EXISTS entitlements (
110	    entitlement_id TEXT PRIMARY KEY,
111	    seats_total    BIGINT NOT NULL CHECK (seats_total > 0),
112	    quota_total    BIGINT NOT NULL CHECK (quota_total > 0),
113	    used_amount    BIGINT NOT NULL DEFAULT 0 CHECK (used_amount >= 0),
114	    valid_from     TIMESTAMPTZ NOT NULL,
115	    valid_to       TIMESTAMPTZ NOT NULL,
116	    created_at     TIMESTAMPTZ NOT NULL DEFAULT now()
117	);
118	CREATE TABLE IF NOT EXISTS reservations (
119	    entitlement_id TEXT NOT NULL REFERENCES entitlements (entitlement_id),
120	    reservation_id TEXT NOT NULL,
121	    amount         BIGINT NOT NULL CHECK (amount > 0),
122	    status         TEXT NOT NULL DEFAULT 'pending'
123	                   CHECK (status IN ('pending', 'confirmed', 'released')),
124	    settled_at     TIMESTAMPTZ,
125	    created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
126	    PRIMARY KEY (entitlement_id, reservation_id)
127	);`)
128		if err != nil {
129			return fmt.Errorf("migrate schema: %w", err)
130		}
131		return nil
132	}
133	
134	// CreateEntitlementInput carries the raw creation parameters.
135	type CreateEntitlementInput struct {
136		EntitlementID string
137		SeatsTotal    *int64
138		QuotaTotal    *int64
139		ValidFrom     time.Time
140		ValidTo       time.Time
141	}
142	
143	// CreateEntitlement validates and stores a new entitlement. Invalid input
144	// fails before anything is written.
145	func (s *Store) CreateEntitlement(ctx context.Context, in CreateEntitlementInput) (Entitlement, error) {
146		if err := validIdentifier("entitlement_id", in.EntitlementID); err != nil {
147			return Entitlement{}, err
148		}
149		if in.QuotaTotal == nil || *in.QuotaTotal <= 0 {
150			return Entitlement{}, fail(CodeInvalidRequest, "quota_total is required and must be a positive integer")
151		}
152		seats := *in.QuotaTotal
153		if in.SeatsTotal != nil {
154			if *in.SeatsTotal <= 0 {
155				return Entitlement{}, fail(CodeInvalidRequest, "seats_total must be a positive integer")
156			}
157			seats = *in.SeatsTotal
158		}
159		if in.ValidFrom.IsZero() || in.ValidTo.IsZero() {
160			return Entitlement{}, fail(CodeInvalidRequest, "valid_from and valid_to are required (RFC 3339 timestamps)")
161		}
162		if !in.ValidFrom.Before(in.ValidTo) {
163			return Entitlement{}, fail(CodeInvalidRequest, "valid_from must be before valid_to")
164		}
165		ent := Entitlement{
166			EntitlementID: in.EntitlementID,
167			SeatsTotal:    seats,
168			QuotaTotal:    *in.QuotaTotal,
169			ValidFrom:     in.ValidFrom.UTC(),
170			ValidTo:       in.ValidTo.UTC(),
171		}
172		_, err := s.pool.Exec(ctx, `
173	INSERT INTO entitlements (entitlement_id, seats_total, quota_total, valid_from, valid_to)
174	VALUES ($1, $2, $3, $4, $5)`,
175			ent.EntitlementID, ent.SeatsTotal, ent.QuotaTotal, ent.ValidFrom, ent.ValidTo)
176		if err != nil {
177			var pgErr *pgconn.PgError
178			if errors.As(err, &pgErr) && pgErr.Code == "23505" {
179				return Entitlement{}, fail(CodeEntitlementExists, "entitlement %q already exists", ent.EntitlementID)
180			}
181			return Entitlement{}, fmt.Errorf("insert entitlement: %w", err)
182		}
183		return ent, nil
184	}
185	
186	// entitlementRow is the locked state shared by the mutating flows.
187	type entitlementRow struct {
188		quotaTotal int64
189		usedAmount int64
190		validFrom  time.Time
191		validTo    time.Time
192		now        time.Time
193	}
194	
195	// lockEntitlement takes the per-entitlement serialization lock inside tx.
196	func lockEntitlement(ctx context.Context, tx pgx.Tx, entitlementID string) (entitlementRow, error) {
197		var row entitlementRow
198		err := tx.QueryRow(ctx, `
199	SELECT quota_total, used_amount, valid_from, valid_to, now()
200	FROM entitlements WHERE entitlement_id = $1 FOR UPDATE`, entitlementID).
201			Scan(&row.quotaTotal, &row.usedAmount, &row.validFrom, &row.validTo, &row.now)
202		if errors.Is(err, pgx.ErrNoRows) {
203			return entitlementRow{}, fail(CodeEntitlementNotFound, "entitlement %q does not exist", entitlementID)
204		}
205		if err != nil {
206			return entitlementRow{}, fmt.Errorf("lock entitlement: %w", err)
207		}
208		return row, nil
209	}
210	
211	func pendingAmount(ctx context.Context, tx pgx.Tx, entitlementID string) (int64, error) {
212		var pending int64
213		err := tx.QueryRow(ctx, `
214	SELECT COALESCE(SUM(amount), 0) FROM reservations
215	WHERE entitlement_id = $1 AND status = 'pending'`, entitlementID).Scan(&pending)
216		if err != nil {
217			return 0, fmt.Errorf("sum pending reservations: %w", err)
218		}
219		return pending, nil
220	}
221	
222	// CreateReservation places a quota hold. The caller-supplied reservationID is
223	// unique per entitlement: resubmitting it with the same amount returns the
224	// original reservation without consuming quota again (created=false);
225	// resubmitting it with a different amount fails without changing state.
226	func (s *Store) CreateReservation(ctx context.Context, entitlementID, reservationID string, amount int64) (Reservation, bool, error) {
227		if err := validIdentifier("reservation_id", reservationID); err != nil {
228			return Reservation{}, false, err
229		}
230		if amount <= 0 {
231			return Reservation{}, false, fail(CodeInvalidRequest, "amount is required and must be a positive integer")
232		}
233		tx, err := s.pool.Begin(ctx)
234		if err != nil {
235			return Reservation{}, false, fmt.Errorf("begin transaction: %w", err)
236		}
237		defer func() { _ = tx.Rollback(ctx) }()
238	
239		ent, err := lockEntitlement(ctx, tx, entitlementID)
240		if err != nil {
241			return Reservation{}, false, err
242		}
243	
244		var existing Reservation
245		err = tx.QueryRow(ctx, `
246	SELECT reservation_id, amount, status, settled_at, created_at
247	FROM reservations WHERE entitlement_id = $1 AND reservation_id = $2`,
248			entitlementID, reservationID).
249			Scan(&existing.ReservationID, &existing.Amount, &existing.Status, &existing.SettledAt, &existing.CreatedAt)
250		if err != nil && !errors.Is(err, pgx.ErrNoRows) {
251			return Reservation{}, false, fmt.Errorf("load reservation: %w", err)
252		}
253		if err == nil {
254			if existing.Amount != amount {
255				return Reservation{}, false, fail(CodeReservationParamChanged,
256					"reservation %q already exists with amount %d, not %d", reservationID, existing.Amount, amount)
257			}
258			return existing, false, tx.Commit(ctx)
259		}
260	
261		if ent.now.Before(ent.validFrom) || !ent.now.Before(ent.validTo) {
262			return Reservation{}, false, fail(CodeEntitlementNotActive,
263				"entitlement %q is not in its validity window", entitlementID)
264		}
265		pending, err := pendingAmount(ctx, tx, entitlementID)
266		if err != nil {
267			return Reservation{}, false, err
268		}
269		if ent.usedAmount+pending+amount > ent.quotaTotal {
270			return Reservation{}, false, fail(CodeInsufficientQuota,
271				"requested %d but only %d of %d quota available", amount, ent.quotaTotal-ent.usedAmount-pending, ent.quotaTotal)
272		}
273		var created Reservation
274		err = tx.QueryRow(ctx, `
275	INSERT INTO reservations (entitlement_id, reservation_id, amount)
276	VALUES ($1, $2, $3)
277	RETURNING reservation_id, amount, status, settled_at, created_at`,
278			entitlementID, reservationID, amount).
279			Scan(&created.ReservationID, &created.Amount, &created.Status, &created.SettledAt, &created.CreatedAt)
280		if err != nil {
281			return Reservation{}, false, fmt.Errorf("insert reservation: %w", err)
282		}
283		if err := tx.Commit(ctx); err != nil {
284			return Reservation{}, false, fmt.Errorf("commit reservation: %w", err)
285		}
286		return created, true, nil
287	}
288	
289	// SettleReservation settles a pending reservation exactly once: confirm moves
290	// its amount to used quota, release returns it to available quota. Any
291	// further settlement attempt fails without effect.
292	func (s *Store) SettleReservation(ctx context.Context, entitlementID, reservationID, action string) (Reservation, error) {
293		if action != ActionConfirm && action != ActionRelease {
294			return Reservation{}, fail(CodeInvalidRequest, "action must be %q or %q", ActionConfirm, ActionRelease)
295		}
296		tx, err := s.pool.Begin(ctx)
297		if err != nil {
298			return Reservation{}, fmt.Errorf("begin transaction: %w", err)
299		}
300		defer func() { _ = tx.Rollback(ctx) }()
301	
302		if _, err := lockEntitlement(ctx, tx, entitlementID); err != nil {
303			return Reservation{}, err
304		}
305		var reservation Reservation
306		err = tx.QueryRow(ctx, `
307	SELECT reservation_id, amount, status, settled_at, created_at
308	FROM reservations WHERE entitlement_id = $1 AND reservation_id = $2`,
309			entitlementID, reservationID).
310			Scan(&reservation.ReservationID, &reservation.Amount, &reservation.Status, &reservation.SettledAt, &reservation.CreatedAt)
311		if errors.Is(err, pgx.ErrNoRows) {
312			return Reservation{}, fail(CodeReservationNotFound,
313				"reservation %q does not exist on entitlement %q", reservationID, entitlementID)
314		}
315		if err != nil {
316			return Reservation{}, fmt.Errorf("load reservation: %w", err)
317		}
318		if reservation.Status != StatusPending {
319			return Reservation{}, fail(CodeReservationSettled,
320				"reservation %q is already %s", reservationID, reservation.Status)
321		}
322	
323		newStatus := StatusReleased
324		if action == ActionConfirm {
325			newStatus = StatusConfirmed
326			if _, err := tx.Exec(ctx, `
327	UPDATE entitlements SET used_amount = used_amount + $1 WHERE entitlement_id = $2`,
328				reservation.Amount, entitlementID); err != nil {
329				return Reservation{}, fmt.Errorf("consume quota: %w", err)
330			}
331		}
332		err = tx.QueryRow(ctx, `
333	UPDATE reservations SET status = $1, settled_at = now()
334	WHERE entitlement_id = $2 AND reservation_id = $3
335	RETURNING reservation_id, amount, status, settled_at, created_at`,
336			newStatus, entitlementID, reservationID).
337			Scan(&reservation.ReservationID, &reservation.Amount, &reservation.Status, &reservation.SettledAt, &reservation.CreatedAt)
338		if err != nil {
339			return Reservation{}, fmt.Errorf("settle reservation: %w", err)
340		}
341		if err := tx.Commit(ctx); err != nil {
342			return Reservation{}, fmt.Errorf("commit settlement: %w", err)
343		}
344		return reservation, nil
345	}
346	
347	// GetView returns the quota breakdown and reservation list for an
348	// entitlement, consistent with the committed state.
349	func (s *Store) GetView(ctx context.Context, entitlementID string) (View, error) {
350		tx, err := s.pool.BeginTx(ctx, pgx.TxOptions{IsoLevel: pgx.RepeatableRead, AccessMode: pgx.ReadOnly})
351		if err != nil {
352			return View{}, fmt.Errorf("begin transaction: %w", err)
353		}
354		defer func() { _ = tx.Rollback(ctx) }()
355	
356		var view View
357		var now time.Time
358		err = tx.QueryRow(ctx, `
359	SELECT seats_total, quota_total, used_amount, valid_from, valid_to, now()
360	FROM entitlements WHERE entitlement_id = $1`, entitlementID).
361			Scan(&view.SeatsTotal, &view.QuotaTotal, &view.UsedAmount, &view.ValidFrom, &view.ValidTo, &now)
362		if errors.Is(err, pgx.ErrNoRows) {
363			return View{}, fail(CodeEntitlementNotFound, "entitlement %q does not exist", entitlementID)
364		}
365		if err != nil {
366			return View{}, fmt.Errorf("load entitlement: %w", err)
367		}
368		view.EntitlementID = entitlementID
369		switch {
370		case now.Before(view.ValidFrom):
371			view.Status = "pending"
372		case now.Before(view.ValidTo):
373			view.Status = "active"
374		default:
375			view.Status = "expired"
376		}
377		view.ReservedAmount, err = pendingAmount(ctx, tx, entitlementID)
378		if err != nil {
379			return View{}, err
380		}
381		view.AvailableAmount = view.QuotaTotal - view.UsedAmount - view.ReservedAmount
382	
383		rows, err := tx.Query(ctx, `
384	SELECT reservation_id, amount, status, settled_at, created_at
385	FROM reservations WHERE entitlement_id = $1
386	ORDER BY created_at, reservation_id`, entitlementID)
387		if err != nil {
388			return View{}, fmt.Errorf("list reservations: %w", err)
389		}
390		defer rows.Close()
391		view.Reservations = []Reservation{}
392		for rows.Next() {
393			var r Reservation
394			if err := rows.Scan(&r.ReservationID, &r.Amount, &r.Status, &r.SettledAt, &r.CreatedAt); err != nil {
395				return View{}, fmt.Errorf("scan reservation: %w", err)
396			}
397			view.Reservations = append(view.Reservations, r)
398		}
399		if err := rows.Err(); err != nil {
400			return View{}, fmt.Errorf("list reservations: %w", err)
401		}
402		if err := tx.Commit(ctx); err != nil {
403			return View{}, fmt.Errorf("commit view: %w", err)
404		}
405		return view, nil
406	}
