1	package httpapi
2	
3	import (
4		"context"
5		"encoding/json"
6		"errors"
7		"net/http"
8		"time"
9	
10		"github.com/lansolocoder/cla03-entitlement-service/internal/entitlements"
11	)
12	
13	// Service is the entitlement domain surface the HTTP layer needs.
14	type Service interface {
15		CreateEntitlement(ctx context.Context, in entitlements.CreateEntitlementInput) (entitlements.Entitlement, error)
16		CreateReservation(ctx context.Context, entitlementID, reservationID string, amount int64) (entitlements.Reservation, bool, error)
17		SettleReservation(ctx context.Context, entitlementID, reservationID, action string) (entitlements.Reservation, error)
18		GetView(ctx context.Context, entitlementID string) (entitlements.View, error)
19	}
20	
21	func New(checkDatabase func(context.Context) error, service Service) http.Handler {
22		mux := http.NewServeMux()
23		mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, _ *http.Request) {
24			respond(w, http.StatusOK, `{"status":"ok"}`)
25		})
26		mux.HandleFunc("GET /readyz", func(w http.ResponseWriter, r *http.Request) {
27			ctx, cancel := context.WithTimeout(r.Context(), time.Second)
28			defer cancel()
29			if err := checkDatabase(ctx); err != nil {
30				respond(w, http.StatusServiceUnavailable, `{"status":"unavailable"}`)
31				return
32			}
33			respond(w, http.StatusOK, `{"status":"ready"}`)
34		})
35	
36		h := &handlers{service: service}
37		mux.HandleFunc("POST /entitlements", h.createEntitlement)
38		mux.HandleFunc("GET /entitlements/{entitlementID}", h.getEntitlement)
39		mux.HandleFunc("POST /entitlements/{entitlementID}/reservations", h.createReservation)
40		mux.HandleFunc("POST /entitlements/{entitlementID}/reservations/{reservationID}/confirm", h.settle(entitlements.ActionConfirm))
41		mux.HandleFunc("POST /entitlements/{entitlementID}/reservations/{reservationID}/release", h.settle(entitlements.ActionRelease))
42		return mux
43	}
44	
45	type handlers struct {
46		service Service
47	}
48	
49	type createEntitlementRequest struct {
50		EntitlementID string `json:"entitlement_id"`
51		SeatsTotal    *int64 `json:"seats_total"`
52		QuotaTotal    *int64 `json:"quota_total"`
53		ValidFrom     string `json:"valid_from"`
54		ValidTo       string `json:"valid_to"`
55	}
56	
57	func (h *handlers) createEntitlement(w http.ResponseWriter, r *http.Request) {
58		var req createEntitlementRequest
59		if !decode(w, r, &req) {
60			return
61		}
62		validFrom, errFrom := time.Parse(time.RFC3339, req.ValidFrom)
63		validTo, errTo := time.Parse(time.RFC3339, req.ValidTo)
64		if req.ValidFrom == "" || req.ValidTo == "" || errFrom != nil || errTo != nil {
65			respondError(w, &entitlements.Error{
66				Code:    entitlements.CodeInvalidRequest,
67				Message: "valid_from and valid_to must be RFC 3339 timestamps, e.g. 2026-01-01T00:00:00Z",
68			})
69			return
70		}
71		ent, err := h.service.CreateEntitlement(r.Context(), entitlements.CreateEntitlementInput{
72			EntitlementID: req.EntitlementID,
73			SeatsTotal:    req.SeatsTotal,
74			QuotaTotal:    req.QuotaTotal,
75			ValidFrom:     validFrom,
76			ValidTo:       validTo,
77		})
78		if err != nil {
79			respondError(w, err)
80			return
81		}
82		respondJSON(w, http.StatusCreated, ent)
83	}
84	
85	type createReservationRequest struct {
86		ReservationID string `json:"reservation_id"`
87		Amount        *int64 `json:"amount"`
88	}
89	
90	func (h *handlers) createReservation(w http.ResponseWriter, r *http.Request) {
91		var req createReservationRequest
92		if !decode(w, r, &req) {
93			return
94		}
95		if req.Amount == nil {
96			respondError(w, &entitlements.Error{
97				Code:    entitlements.CodeInvalidRequest,
98				Message: "amount is required and must be a positive integer",
99			})
100			return
101		}
102		reservation, created, err := h.service.CreateReservation(
103			r.Context(), r.PathValue("entitlementID"), req.ReservationID, *req.Amount)
104		if err != nil {
105			respondError(w, err)
106			return
107		}
108		status := http.StatusOK
109		if created {
110			status = http.StatusCreated
111		}
112		respondJSON(w, status, reservation)
113	}
114	
115	func (h *handlers) settle(action string) http.HandlerFunc {
116		return func(w http.ResponseWriter, r *http.Request) {
117			reservation, err := h.service.SettleReservation(
118				r.Context(), r.PathValue("entitlementID"), r.PathValue("reservationID"), action)
119			if err != nil {
120				respondError(w, err)
121				return
122			}
123			respondJSON(w, http.StatusOK, reservation)
124		}
125	}
126	
127	func (h *handlers) getEntitlement(w http.ResponseWriter, r *http.Request) {
128		view, err := h.service.GetView(r.Context(), r.PathValue("entitlementID"))
129		if err != nil {
130			respondError(w, err)
131			return
132		}
133		respondJSON(w, http.StatusOK, view)
134	}
135	
136	// decode parses a JSON request body strictly; on failure it writes the error
137	// response and returns false.
138	func decode(w http.ResponseWriter, r *http.Request, target any) bool {
139		decoder := json.NewDecoder(r.Body)
140		decoder.DisallowUnknownFields()
141		if err := decoder.Decode(target); err != nil {
142			respondError(w, &entitlements.Error{
143				Code:    entitlements.CodeInvalidRequest,
144				Message: "request body must be a JSON object with the documented fields",
145			})
146			return false
147		}
148		return true
149	}
150	
151	// errorStatus maps stable domain error codes to HTTP statuses.
152	var errorStatus = map[string]int{
153		entitlements.CodeInvalidRequest:          http.StatusBadRequest,
154		entitlements.CodeEntitlementExists:       http.StatusConflict,
155		entitlements.CodeEntitlementNotFound:     http.StatusNotFound,
156		entitlements.CodeEntitlementNotActive:    http.StatusUnprocessableEntity,
157		entitlements.CodeInsufficientQuota:       http.StatusUnprocessableEntity,
158		entitlements.CodeReservationNotFound:     http.StatusNotFound,
159		entitlements.CodeReservationParamChanged: http.StatusConflict,
160		entitlements.CodeReservationSettled:      http.StatusConflict,
161	}
162	
163	func respondError(w http.ResponseWriter, err error) {
164		var domainErr *entitlements.Error
165		if !errors.As(err, &domainErr) {
166			respondJSON(w, http.StatusInternalServerError, map[string]any{
167				"error": map[string]string{"code": "internal", "message": "internal server error"},
168			})
169			return
170		}
171		status, ok := errorStatus[domainErr.Code]
172		if !ok {
173			respondJSON(w, http.StatusInternalServerError, map[string]any{
174				"error": map[string]string{"code": "internal", "message": "internal server error"},
175			})
176			return
177		}
178		respondJSON(w, status, map[string]any{
179			"error": map[string]string{"code": domainErr.Code, "message": domainErr.Message},
180		})
181	}
182	
183	func respondJSON(w http.ResponseWriter, status int, body any) {
184		encoded, err := json.Marshal(body)
185		if err != nil {
186			respond(w, http.StatusInternalServerError, `{"error":{"code":"internal","message":"internal server error"}}`)
187			return
188		}
189		respond(w, status, string(encoded))
190	}
191	
192	func respond(w http.ResponseWriter, status int, body string) {
193		w.Header().Set("Content-Type", "application/json")
194		w.Header().Set("Cache-Control", "no-store")
195		w.WriteHeader(status)
196		_, _ = w.Write([]byte(body + "\n"))
197	}
