1	package entitlements
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"os"
8		"sync"
9		"testing"
10		"time"
11	
12		"github.com/jackc/pgx/v5/pgxpool"
13	)
14	
15	// Integration tests run against a real PostgreSQL when TEST_DATABASE_URL is
16	// set, e.g.:
17	//
18	//	TEST_DATABASE_URL='postgres://127.0.0.1:15432/entitlements?sslmode=disable' go test ./...
19	func testStore(t *testing.T) *Store {
20		t.Helper()
21		databaseURL := os.Getenv("TEST_DATABASE_URL")
22		if databaseURL == "" {
23			t.Skip("TEST_DATABASE_URL is not set")
24		}
25		ctx := context.Background()
26		pool, err := pgxpool.New(ctx, databaseURL)
27		if err != nil {
28			t.Fatalf("connect: %v", err)
29		}
30		t.Cleanup(pool.Close)
31		store := NewStore(pool)
32		if err := store.Migrate(ctx); err != nil {
33			t.Fatalf("migrate: %v", err)
34		}
35		return store
36	}
37	
38	func ptr(v int64) *int64 { return &v }
39	
40	// uniqueID generates a distinct entitlement ID per test so tests can share
41	// one database.
42	func uniqueID(t *testing.T) string {
43		t.Helper()
44		return fmt.Sprintf("ent-%d", time.Now().UnixNano())
45	}
46	
47	func mustCreate(t *testing.T, store *Store, id string, quota int64, from, to time.Time) {
48		t.Helper()
49		_, err := store.CreateEntitlement(context.Background(), CreateEntitlementInput{
50			EntitlementID: id, QuotaTotal: ptr(quota), ValidFrom: from, ValidTo: to,
51		})
52		if err != nil {
53			t.Fatalf("create entitlement: %v", err)
54		}
55	}
56	
57	func activeWindow() (time.Time, time.Time) {
58		return time.Now().Add(-time.Hour), time.Now().Add(time.Hour)
59	}
60	
61	func wantCode(t *testing.T, err error, code string) {
62		t.Helper()
63		var domainErr *Error
64		if !errors.As(err, &domainErr) || domainErr.Code != code {
65			t.Fatalf("want error code %q, got %v", code, err)
66		}
67	}
68	
69	func TestCreateEntitlementValidation(t *testing.T) {
70		store := testStore(t)
71		from, to := activeWindow()
72		id := uniqueID(t)
73		for _, tc := range []struct {
74			name string
75			in   CreateEntitlementInput
76		}{
77			{"empty id", CreateEntitlementInput{QuotaTotal: ptr(10), ValidFrom: from, ValidTo: to}},
78			{"bad id chars", CreateEntitlementInput{EntitlementID: "bad id!", QuotaTotal: ptr(10), ValidFrom: from, ValidTo: to}},
79			{"missing quota", CreateEntitlementInput{EntitlementID: id, ValidFrom: from, ValidTo: to}},
80			{"zero quota", CreateEntitlementInput{EntitlementID: id, QuotaTotal: ptr(0), ValidFrom: from, ValidTo: to}},
81			{"negative seats", CreateEntitlementInput{EntitlementID: id, QuotaTotal: ptr(10), SeatsTotal: ptr(-1), ValidFrom: from, ValidTo: to}},
82			{"empty window", CreateEntitlementInput{EntitlementID: id, QuotaTotal: ptr(10), ValidFrom: to, ValidTo: from}},
83		} {
84			t.Run(tc.name, func(t *testing.T) {
85				wantCode(t, store.createForTest(tc.in), CodeInvalidRequest)
86				if _, err := store.GetView(context.Background(), tc.in.EntitlementID); err == nil && tc.in.EntitlementID != "" {
87					t.Fatalf("invalid create wrote entitlement %q", tc.in.EntitlementID)
88				}
89			})
90		}
91	}
92	
93	// createForTest keeps the table-driven test readable.
94	func (s *Store) createForTest(in CreateEntitlementInput) error {
